import pathlib,pandas as pd,numpy as np,json,hashlib,datetime
P=pathlib.Path(__file__).parent;U=P/'unblinding_materials';O=P/'review_output';B=O/'blind_submission';C=O/'unblinded_comparison'
key=pd.read_csv(U/'unblinding/cell_identifier_key.tsv.gz',sep='\t');clkey=pd.read_csv(U/'unblinding/cluster_identifier_key.tsv',sep='\t');clkey=clkey[clkey.resolution=='r10'];a=pd.read_csv(U/'tables/all_cell_reannotation_v1.tsv.gz',sep='\t',usecols=['cell_id','dataset','sample','patient_id','r10','curation_id','proposed_lineage','state','status','copykat_call','infercnv_call','CNV_evidence_current','identity_interpretation','full_library','reference_resolution_disagreement','reference_patient_disagreement']);assert len(a)==876648;assert not a.duplicated(['dataset','cell_id']).any();m=a.merge(key,left_on=['dataset','cell_id'],right_on=['original_dataset','original_cell_id'],suffixes=('_original','_anonymous'),validate='one_to_one',how='left');assert m.cell_id_anonymous.notna().all();m=m.merge(clkey[['dataset','original_cluster','cluster_id']],left_on=['dataset','r10'],right_on=['dataset','original_cluster'],validate='many_to_one');s=pd.read_pickle(O/'cell_structure.pkl');r=m.merge(s[['cell_id','r10']],left_on='cell_id_anonymous',right_on='cell_id',suffixes=('','_roster'),validate='one_to_one');assert (r.cluster_id==r.r10_roster).all();bd=pd.read_csv(B/'cluster_review_details.tsv',sep='\t');m=m.merge(bd[['cluster_id','lineage_code','lineage_confidence','malignancy_assessment']],on='cluster_id',validate='many_to_one')
cols=['cell_id_anonymous','dataset','source_id','sample_id','patient_id_anonymous','cluster_id','curation_id','proposed_lineage','lineage_code','lineage_confidence','copykat_call','infercnv_call','CNV_evidence_current','malignancy_assessment'];m[cols].rename(columns={'cell_id_anonymous':'cell_id','patient_id_anonymous':'patient_id'}).to_csv(C/'cell_annotation_comparison.tsv.gz',sep='\t',index=False)
z=m.groupby(['cluster_id','CNV_evidence_current'],dropna=False).size().rename('cells').reset_index();z['fraction_in_cluster']=z.cells/z.groupby('cluster_id').cells.transform('sum');z.to_csv(C/'proposed_CNV_cluster_composition.tsv',sep='\t',index=False)
z=m.groupby(['cluster_id','identity_interpretation'],dropna=False).size().rename('cells').reset_index();z.to_csv(C/'proposed_identity_interpretation_counts.tsv',sep='\t',index=False)
f=m.groupby('cluster_id').full_library.sum();blindst=pd.read_csv(O/'cluster_structure_review.tsv',sep='\t').set_index('cluster_id');assert f.sort_index().equals(blindst.full_library.sort_index())
old=pd.read_csv(U/'unblinding/old_frozen_to_new_annotation.tsv.gz',sep='\t');old=old.merge(m[['dataset','cell_id_original','cell_id_anonymous','cluster_id','lineage_code','malignancy_assessment']],left_on=['dataset','cell_id'],right_on=['dataset','cell_id_original'],validate='many_to_one',how='left');assert old.cluster_id.notna().all();old.to_csv(C/'historical_sets_cell_comparison.tsv.gz',sep='\t',index=False)
for typ,field in [('supported','supported_class_id'),('expanded','expanded_class_id')]:
 z=old[old[field].notna()].groupby([field,'proposed_lineage','lineage_code']).size().rename('cells').reset_index();z.to_csv(C/f'historical_{typ}_comparison.tsv',sep='\t',index=False);print(typ,z.to_string(index=False))
manifest=pd.read_csv(U/'resources/COPYKAT_PROFILE_MANIFEST.tsv',sep='\t');maps=json.loads((U/'unblinding/identifier_maps.json').read_text());cm=pd.read_csv(P/'copykat_cell_continuous_metrics.tsv.gz',sep='\t',usecols=['sample_id']);covered=set(cm.sample_id);print('MAP samples example',list(maps['samples'].items())[:2]);mapped=manifest['sample'].map(maps['samples']);print('MANIFEST samples',len(manifest),'unique',manifest['sample'].nunique(),'mappedmissing',mapped.isna().sum(),'not covered',manifest.loc[~mapped.isin(covered),'sample'].tolist());print('metadatacoverage',len(covered));print('CNV counts',a.CNV_evidence_current.value_counts().to_dict());print('IDENTITY',a.identity_interpretation.value_counts().to_dict());print('allcell copykat sample n',a.loc[a.copykat_call.notna(),'sample'].nunique());print('copykat labels',a.copykat_call.value_counts(dropna=False).to_dict())
(C/'cell_mapping_validation.json').write_text(json.dumps({'cells':len(a),'all_cells_mapped':True,'cluster_membership_exact':True,'cluster_full_libraries_match':True,'historical_cells':len(old),'blind_submission_untouched':True},indent=2))
